const response = $input.first().json;
const messages = response.result || [];

if (messages.length === 0) {
  // No new messages, stop the workflow
  return [];
}

// Save the last update ID so we don't reprocess
const lastId = messages[messages.length - 1].update_id;
$workflow.staticData.lastUpdateId = lastId + 1;

// Process only messages that have text
const results = [];
for (const update of messages) {
  const msg = update.message;
  if (msg && msg.text) {
    results.push({
      json: {
        chatId: msg.chat.id,
        messageText: msg.text,
        raw: update
      }
    });
  }
}

return results;

const items = $input.all();

return items.map(item => {
  const geminiResponse = item.json;
  const chatId = item.json._chatId || $node['Process Messages'].json.chatId;
  const originalText = item.json._originalText || $node['Process Messages'].json.messageText;
  const timestamp = new Date().toISOString();

  let parsed;
  try {
    const rawText = geminiResponse.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    parsed = JSON.parse(rawText);
  } catch (e) {
    parsed = {
      qualified: false,
      reasoning: 'Error parsing the qualification response.'
    };
  }

  const qualified = parsed.qualified === true;
  const reasoning = parsed.reasoning || 'No reasoning provided.';
  const header = qualified ? 'Qualified' : 'Not Qualified';
  const replyText = `*${header}*\n\n${reasoning}`;

  return {
    json: {
      chatId: chatId,
      replyText: replyText,
      decision: header,
      reason: reasoning,
      originalText: originalText,
      timestamp: timestamp
    }
  };
});
